init_db2();
init_schema2();
async function listModels(filters) {
  let query = db.select().from(aiModels);
  const conditions = [];
  if (filters?.status) conditions.push(eq(aiModels.status, filters.status));
  if (filters?.category) conditions.push(eq(aiModels.category, filters.category));
  if (conditions.length) {
    query = query.where(and(...conditions));
  }
  return await query.orderBy(desc(aiModels.downloads)).limit(filters?.limit || 50);
}
async function getModelById(id) {
  const [model] = await db.select().from(aiModels).where(eq(aiModels.id, id)).limit(1);
  return model;
}
async function createModel(data) {
  const result = await db.insert(aiModels).values({ ...data, status: "draft" });
  return { id: result[0].insertId };
}
async function purchaseModel(data) {
  const result = await db.insert(modelPurchases).values({ ...data, status: "active" });
  await db.update(aiModels).set({ downloads: sql`${aiModels.downloads} + 1` }).where(eq(aiModels.id, data.modelId));
  return { id: result[0].insertId };
}
async function getUserPurchases(userId) {
  return await db.select().from(modelPurchases).where(eq(modelPurchases.userId, userId)).orderBy(desc(modelPurchases.createdAt));
}
async function addReview(data) {
  const result = await db.insert(modelReviews).values(data);
  const [avg2] = await db.select({ avg: sql`AVG(rating)`, count: sql`COUNT(*)` }).from(modelReviews).where(eq(modelReviews.modelId, data.modelId));
  await db.update(aiModels).set({ rating: avg2.avg, reviewCount: avg2.count }).where(eq(aiModels.id, data.modelId));
  return { id: result[0].insertId };
}
async function getModelReviews(modelId) {
  return await db.select().from(modelReviews).where(eq(modelReviews.modelId, modelId)).orderBy(desc(modelReviews.createdAt));
}

